import {cms} from '@/cms'
import {Query} from 'alinea'

const menu = await cms.find({
  root: cms.workspaces.main.pages,
  locale: 'en',
  level: 0,
  select: {
    title: Query.title,
    url: Query.url,
    children: Query.children({
      select: {
        title: Query.title,
