import {cms} from '@/cms'
import {BlogPost} from '@/schema'
import {Query} from 'alinea'

// Everything a post card needs
export const postCard = {
  title: Query.title,
  url: Query.url,
  date: BlogPost.publishDate,
  cover: BlogPost.cover
}

export type PostCard = Awaited<ReturnType<typeof latestPosts>>[number]

export function latestPosts(take = 3) {
  return cms.find({
    type: BlogPost,
    select: postCard,
    orderBy: {desc: BlogPost.publishDate},
    take
  })
}

export function featuredPosts() {
  return cms.find({
    type: BlogPost,
    filter: {featured: true},
    select: {...postCard, intro: BlogPost.intro}
  })
}

import {cms} from '@/cms'
import {Query} from 'alinea'

export function suggest(term: string) {
  return cms.find({
    search: term,
    disableSync: true,
    take: 5,
    select: {title: Query.title, url: Query.url}
  })
}
